package com.example.case1.analytics.consumer; import com.example.case1.analytics.model.TransactionEvent; import com.example.case1.analytics.sink.AnalyticsSink; import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.*; import java.util.UUID; import static org.mockito.Mockito.*;
class TransactionEventConsumerTest { @Test void parsesAndForwardsEvent() throws Exception {ObjectMapper mapper=new ObjectMapper().registerModule(new JavaTimeModule()); AnalyticsSink sink=mock(AnalyticsSink.class); TransactionEvent event=new TransactionEvent(UUID.randomUUID(),UUID.randomUUID(),"tx1",BigDecimal.TEN,"USD",LocalDate.now(),"ACCEPTED",Instant.now()); new TransactionEventConsumer(mapper,sink).consume(mapper.writeValueAsString(event)); verify(sink).write(event);} }
